def apply_bpe_merges(tokens, merge_rules):
    current = list(tokens)
    for left, right, merged in merge_rules:
        out = []
        i = 0
        while i < len(current):
            if i + 1 < len(current) and current[i] == left and current[i + 1] == right:
                out.append(merged)
                i += 2
            else:
                out.append(current[i])
                i += 1
        current = out
    return current

def llm_cost(input_tokens, output_tokens, input_per_million=2.50, output_per_million=10.00):
    cost = input_tokens / 1_000_000 * input_per_million + output_tokens / 1_000_000 * output_per_million
    return round(cost, 6)

