import re


def validate_and_heal_json(raw, required_keys):
    text = raw.strip()
    fence = re.search(r'```(?:json)?\s*(.*?)\s*```', text, re.S)
    if fence:
        text = fence.group(1)
    try:
        data = json.loads(text)
    except json.JSONDecodeError:
        return {'valid': False, 'error': 'JSON_SYNTAX_ERROR'}
    missing = [k for k in required_keys if k not in data]
    if missing:
        return {'valid': False, 'error': 'MISSING_KEYS: ' + ', '.join(missing)}
    return {'valid': True, 'data': data}

def validate_type(value, expected):
    if isinstance(value, bool):
        return expected == 'bool'
    types = {'str': str, 'int': int, 'float': float, 'list': list, 'dict': dict, 'bool': bool}
    return isinstance(value, types[expected])

