import math


def search_vector_index(query, docs, top_k=2, filters=None):
    filters = filters or {}

    def cosine(a, b):
        dot = sum(x * y for x, y in zip(a, b))
        na = math.sqrt(sum(x * x for x in a))
        nb = math.sqrt(sum(y * y for y in b))
        return dot / (na * nb) if na and nb else 0.0

    hits = [
        {'id': d['id'], 'score': round(cosine(query, d['embedding']), 4)}
        for d in docs
        if all(d['metadata'].get(k) == v for k, v in filters.items())
    ]
    hits.sort(key=lambda h: h['score'], reverse=True)
    return hits[:top_k]

def chunk_text(text, max_chunk=100, overlap=20):
    chunks = []
    start = 0
    while start < len(text):
        end = min(start + max_chunk, len(text))
        chunks.append(text[start:end])
        if end == len(text):
            break
        start += max_chunk - overlap
    return chunks

def reciprocal_rank_fusion(dense, sparse, k=60):
    scores = {}
    texts = {}
    for results in (dense, sparse):
        for rank, d in enumerate(results, start=1):
            scores[d['id']] = scores.get(d['id'], 0) + 1 / (k + rank)
            texts[d['id']] = d['text']
    fused = [{'id': i, 'text': texts[i], 'rrf_score': round(s, 6)} for i, s in scores.items()]
    fused.sort(key=lambda r: r['rrf_score'], reverse=True)
    return fused

