def arrange_lost_in_middle(chunks):
    if len(chunks) <= 2:
        return list(chunks)
    result = [None] * len(chunks)
    left, right = 0, len(chunks) - 1
    for i, chunk in enumerate(chunks):
        if i % 2 == 0:
            result[right] = chunk
            right -= 1
        else:
            result[left] = chunk
            left += 1
    return result

