def evaluate_faithfulness(context, claims):
    ctx = context.lower()
    unsupported = [c for c in claims if c.lower() not in ctx]
    score = round((len(claims) - len(unsupported)) / len(claims), 2) if claims else 0
    return {'score': score, 'is_grounded': score >= 0.8, 'unsupported': unsupported}

def ragas_composite(faithfulness, relevance, recall):
    scores = [faithfulness, relevance, recall]
    if 0 in scores:
        return 0.0
    return round(3 / sum(1 / s for s in scores), 2)

