def strip_malicious_markup(text):
    text = re.sub(r'!\[.*?\]\(.*?\)', '', text)
    return re.sub(r'<script.*?</script>', '', text, flags=re.I | re.S)

def run_rag_pipeline(query, vector_search, keyword_search, rerank):
    merged, seen = [], set()
    for chunk in vector_search(query) + keyword_search(query):
        if chunk['id'] not in seen:
            seen.add(chunk['id'])
            merged.append(chunk)
    ranked = sorted(rerank(query, merged), key=lambda c: c['score'], reverse=True)[:3]
    context = '\n---\n'.join(c['text'] for c in ranked)
    return {'status': 'RAG_READY', 'top_chunks': ranked, 'prompt': f'Context:\n{context}\n\nQuestion: {query}'}

def update_memory(history, new_turn, max_tokens=100):
    messages = history + [new_turn]
    if sum(m['tokens'] for m in messages) <= max_tokens:
        return {'memory': messages, 'summarized': False}
    older, recent = messages[:-2], messages[-2:]
    summary = {'role': 'system', 'text': 'Summary: discussed ' + ', '.join(m['topic'] for m in older), 'topic': 'summary', 'tokens': 20}
    return {'memory': [summary] + recent, 'summarized': True}

