def parse_react_step(output):
    if 'Final Answer:' in output:
        return {'type': 'FINAL_ANSWER', 'answer': output.split('Final Answer:', 1)[1].strip()}
    step = {'type': 'ACTION_STEP', 'thought': '', 'action': '', 'action_input': ''}
    for line in output.splitlines():
        if line.startswith('Thought:'):
            step['thought'] = line[len('Thought:'):].strip()
        elif line.startswith('Action Input:'):
            step['action_input'] = line[len('Action Input:'):].strip()
        elif line.startswith('Action:'):
            step['action'] = line[len('Action:'):].strip()
    return step

