def parse_sse_chunk(chunk):
    text, done = '', False
    for line in chunk.splitlines():
        if line == 'data: [DONE]':
            done = True
        elif line.startswith('data: '):
            delta = json.loads(line[len('data: '):])['choices'][0]['delta']
            text += delta.get('content', '')
    return {'text': text, 'done': done}

