import math


def cached_response(query, embedding, store, threshold=0.95):
    if query in store['exact']:
        return {'hit': True, 'type': 'EXACT', 'response': store['exact'][query]}
    for entry in store['semantic']:
        e = entry['embedding']
        dot = sum(a * b for a, b in zip(embedding, e))
        norms = math.sqrt(sum(a * a for a in embedding)) * math.sqrt(sum(b * b for b in e))
        if norms and dot / norms >= threshold:
            return {'hit': True, 'type': 'SEMANTIC', 'response': entry['response']}
    return {'hit': False, 'type': 'MISS', 'response': None}

