def vision_tokens(width, height, patch=14):
    px, py = math.ceil(width / patch), math.ceil(height / patch)
    return {'patches_x': px, 'patches_y': py, 'total_tokens': px * py + 1}

def token_bucket(requested, available, capacity=100000):
    if requested > capacity:
        return {'allowed': False, 'remaining': available, 'status': 413}
    if requested > available:
        return {'allowed': False, 'remaining': available, 'status': 429}
    return {'allowed': True, 'remaining': available - requested, 'status': 200}

