def traverse_graph(graph, start, relation):
    props = {n['id']: n['properties'] for n in graph['nodes']}
    return [
        {'entity': e['to'], 'properties': props.get(e['to'], {})}
        for e in graph['edges']
        if e['from'] == start and e['type'] == relation
    ]

def run_ai_platform(query, services):
    if services['is_threat'](query):
        return {'success': False, 'error': 'BLOCKED'}
    cached = services['cache_get'](query)
    if cached is not None:
        return {'success': True, 'source': 'CACHE', 'response': cached}
    sources = services['retrieve'](query)
    response = services['answer'](query, sources)
    services['cache_set'](query, response)
    return {'success': True, 'source': 'RAG', 'response': response, 'sources': sources}

def audit_capstone(scores):
    average = round(sum(scores.values()) / len(scores), 1)
    failed = sorted(m for m, s in scores.items() if s < 70)
    return {'average': average, 'failed': failed, 'certified': average >= 80 and not failed}
